import type { CodeSubtask, RoutingHints } from "./types.ts";
import type { IntentResult } from "./intent-classifier.ts";
import type { ValidationTrace } from "./validation-outcome-detector.ts";

export type SweSubtaskHeuristic = {
  type: CodeSubtask;
  confidence: number;
  reasons: string[];
  hints: RoutingHints;
};

export function buildSweSubtaskHeuristic(intent: IntentResult | null | undefined, validation?: ValidationTrace): SweSubtaskHeuristic | null {
  if (!intent || intent.category !== "code") return null;

  let type = intent.subtask;
  const reasons = [...(intent.subtaskReasons ?? [])];
  let confidence = intent.subtaskConfidence ?? 0.6;

  if (!type && validation?.testOutcome === "failed") {
    type = "testing";
    confidence = 0.72;
    reasons.push("failed test signal");
  }
  if ((!type || type === "implementation") && validation?.buildOutcome === "failed") {
    type = "debugging";
    confidence = Math.max(confidence, 0.75);
    reasons.push("failed build signal");
  }
  if (!type) return null;

  const preferProviders = getPreferredProviders(type, validation);
  const hints: RoutingHints = { preferProviders };

  if ((type === "debugging" || type === "devops") && (validation?.buildOutcome === "failed" || validation?.testOutcome === "failed")) {
    hints.requireProvider = "claude-agent-sdk";
  }

  return {
    type,
    confidence,
    reasons,
    hints,
  };
}

function getPreferredProviders(type: CodeSubtask, validation?: ValidationTrace): string[] {
  switch (type) {
    case "implementation":
      return ["openai-codex", "claude-agent-sdk", "nvidia"];
    case "debugging":
      return validation?.testOutcome === "failed" || validation?.buildOutcome === "failed"
        ? ["claude-agent-sdk", "openai-codex", "google"]
        : ["claude-agent-sdk", "openai-codex"];
    case "refactor":
      return ["claude-agent-sdk", "openai-codex", "google"];
    case "testing":
      return ["openai-codex", "claude-agent-sdk", "google"];
    case "review":
      return ["claude-agent-sdk", "google", "openai-codex"];
    case "devops":
      return ["claude-agent-sdk", "openai-codex", "google"];
    default:
      return ["claude-agent-sdk", "openai-codex"];
  }
}

import type { ShortcutRegistry, Tier } from "./types.ts";

export const DEFAULT_SHORTCUTS: ShortcutRegistry = {
  "@reasoning": { tier: "reasoning", description: "Force reasoning-tier model", pattern: /(^|\s)@reasoning\b/i },
  "@swe": { tier: "swe", description: "Force SWE-tier model", pattern: /(^|\s)@swe\b/i },
  "@long": { tier: "long", description: "Force long-context model", pattern: /(^|\s)@long\b/i },
  "@vision": { tier: "vision", description: "Force vision-capable model", pattern: /(^|\s)@vision\b/i },
  "@fast": { tier: "economy", description: "Force fast/economy model", pattern: /(^|\s)@fast\b/i },
};

export type ShortcutMatch = {
  shortcut: string;
  tier: Tier;
  cleanedPrompt: string;
};

export function parseShortcut(prompt: string, registry: ShortcutRegistry = DEFAULT_SHORTCUTS): ShortcutMatch | null {
  if (!prompt) return null;
  for (const [key, entry] of Object.entries(registry)) {
    if (!entry.pattern.test(prompt)) continue;
    const cleanedPrompt = prompt.replace(entry.pattern, " ").replace(/\s+/g, " ").trim();
    return { shortcut: key, tier: entry.tier, cleanedPrompt };
  }
  return null;
}

export function listShortcuts(registry: ShortcutRegistry = DEFAULT_SHORTCUTS): Array<{ shortcut: string; tier: Tier; description: string }> {
  return Object.entries(registry).map(([shortcut, entry]) => ({
    shortcut,
    tier: entry.tier,
    description: entry.description,
  }));
}

import type { RouteTarget } from "./types.ts";

export type RoutingOrder = "adaptive" | "config";
export type CandidateBuckets = {
  promoted: RouteTarget[];
  normal: RouteTarget[];
  demoted: RouteTarget[];
};

export function parseRoutingOrder(value: unknown): RoutingOrder {
  if (value === undefined) return "adaptive";
  if (value === "adaptive" || value === "config") return value;
  throw new Error(`sortBy must be "adaptive" or "config"; received ${JSON.stringify(value)}`);
}

/**
 * Order candidates without crossing UVI buckets. In config mode, declared order is
 * retained and preferProviders is ignored; requireProvider remains an explicit override.
 */
export function orderCandidateBuckets(
  buckets: CandidateBuckets,
  options: {
    mode: RoutingOrder;
    rankedCompare: (a: RouteTarget, b: RouteTarget) => number;
    preferredCompare?: (a: RouteTarget, b: RouteTarget) => number;
    requireProvider?: string;
    preferProviders?: readonly string[];
  },
): void {
  if (options.mode === "adaptive") {
    buckets.promoted.sort(options.rankedCompare);
    buckets.normal.sort(options.rankedCompare);
    buckets.demoted.sort(options.rankedCompare);
  }

  if (options.requireProvider) {
    const moveToFront = (targets: RouteTarget[]) => {
      const index = targets.findIndex((target) => target.provider === options.requireProvider);
      if (index > 0) targets.unshift(targets.splice(index, 1)[0]);
    };
    moveToFront(buckets.promoted);
    moveToFront(buckets.normal);

    const demotedIndex = buckets.demoted.findIndex((target) => target.provider === options.requireProvider);
    if (demotedIndex >= 0) buckets.normal.unshift(buckets.demoted.splice(demotedIndex, 1)[0]);
  }

  if (options.mode === "adaptive" && options.preferProviders?.length && options.preferredCompare) {
    buckets.promoted.sort(options.preferredCompare);
    buckets.normal.sort(options.preferredCompare);
  }
}

import type { CodeSubtask, Message, Tier } from "./types.ts";

export type IntentCategory = "code" | "creative" | "analysis" | "general";

